const body = $input.first().json.body ?? $input.first().json;
if(body.eventType !== "CONTRACT_ACCEPTED") throw Error("Evento incorreto");
if(!/^[a-f0-9]{40}$/i.test(String(body.eventId||""))) throw Error("Identificador inválido");
if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(body.toEmail||""))) throw Error("E-mail inválido");
const phone=String(body.toWhatsApp||"").replace(/\D/g,"");
if(phone.length<10||phone.length>13||!String(body.contractText||"").trim()) throw Error("Destinatário ou contrato ausente");
const whatsappNumber=phone.startsWith("55")?phone:"55"+phone;
const subject="Seu contrato Dishy — "+String(body.planName||"Plano");
const message="Olá! Seu aceite do contrato do Dishy foi registrado.\n\nPlano: "+String(body.planName||"")+
"\nProtocolo: "+body.eventId+"\nSHA-256: "+String(body.sha256||"")+
"\n\nO documento integral também será enviado por este WhatsApp em partes e para seu e-mail cadastrado. Para consultar sua assinatura, entre no seu painel em https://dishy.com.br/login e abra Meu plano.\n\nNenhum pagamento é cobrado por esta mensagem.";
return [{json:{eventId:body.eventId,toEmail:body.toEmail,toWhatsApp:whatsappNumber,subject,emailText:String(body.contractText),whatsappText:message,planId:body.planId,sha256:body.sha256}}];

const v=$input.first().json;
const full="📄 CONTRATO DISHY — "+String(v.subject||"")+
"\nIdentificador: "+v.eventId+
"\n\n"+String(v.emailText||"");
if(!String(v.emailText||"").trim())throw Error("Contrato vazio");
const chunks=[];
for(let pos=0;pos<full.length;pos+=2800)chunks.push(full.slice(pos,pos+2800));
return chunks.map((part,i)=>({json:{eventId:v.eventId,toWhatsApp:v.toWhatsApp,whatsappText:"Parte "+(i+1)+"/"+chunks.length+"\n"+part}}));
